package gocaller

import (
	"reflect"
	"strings"
	"testing"
)

// Modelled on yarpc-go internal/crossdock/thrift/echo (thriftrw v1.32.0 and
// thriftrw-plugin-yarpc output): the Go method Echo is the Thrift method echo.
const thriftRWTestModule = `// Code generated by thriftrw v1.32.0. DO NOT EDIT.
// @generated

package echo

import thriftreflect "go.uber.org/thriftrw/thriftreflect"

type Echo_Echo_Args struct{}

func (v *Echo_Echo_Args) MethodName() string {
	return "echo"
}

type Echo_Ping_Args struct{}

func (v *Echo_Ping_Args) MethodName() string {
	return "ping_twice"
}

var ThriftModule = &thriftreflect.ThriftModule{
	Name:     "echo",
	Package:  "example.test/thrift/echo",
	FilePath: "echo.thrift",
	SHA1:     "c3e4e93d3bee132394d26e5ec61011e3f76b7f33",
	Raw:      rawIDL,
}

const rawIDL = "service Echo {}"
`

const thriftRWTestClient = `// Code generated by thriftrw-plugin-yarpc
// @generated

package echoclient

import (
	context "context"
	yarpc "go.uber.org/yarpc"
	transport "go.uber.org/yarpc/api/transport"
	thrift "go.uber.org/yarpc/encoding/thrift"
	echo "example.test/thrift/echo"
)

type Interface interface {
	Echo(ctx context.Context, Ping *echo.Ping, opts ...yarpc.CallOption) (*echo.Pong, error)
	Ping(ctx context.Context, opts ...yarpc.CallOption) error
	Unknown(ctx context.Context, opts ...yarpc.CallOption) error
}

func New(c transport.ClientConfig, opts ...thrift.ClientOption) Interface {
	return client{
		c: thrift.New(thrift.Config{
			Service:      "Echo",
			ClientConfig: c,
		}, opts...),
		nwc: thrift.NewNoWire(thrift.Config{
			Service:      "Echo",
			ClientConfig: c,
		}, opts...),
	}
}

type client struct {
	c   thrift.Client
	nwc thrift.NoWireClient
}

func (c client) Echo(ctx context.Context, _Ping *echo.Ping, opts ...yarpc.CallOption) (success *echo.Pong, err error) {
	args := echo.Echo_Echo_Helper.Args(_Ping)
	_, err = c.c.Call(ctx, args, opts...)
	return
}

func (c client) Ping(ctx context.Context, opts ...yarpc.CallOption) (err error) {
	args := echo.Echo_Ping_Helper.Args()
	_, err = c.c.Call(ctx, args, opts...)
	return
}

func (c client) Unknown(ctx context.Context, opts ...yarpc.CallOption) (err error) {
	args := echo.Echo_Missing_Helper.Args()
	_, err = c.c.Call(ctx, args, opts...)
	return
}

func (c client) helper() {}
`

func TestParseThriftRWModuleReadsProvenanceAndWireNames(t *testing.T) {
	module, ok, err := ParseThriftRWModule("thrift/echo/echo.go", thriftRWTestModule)
	if err != nil || !ok {
		t.Fatalf("ParseThriftRWModule = %v, %v", ok, err)
	}
	want := ThriftRWModule{
		Name: "echo", Package: "example.test/thrift/echo", FilePath: "echo.thrift",
		SHA1:        "c3e4e93d3bee132394d26e5ec61011e3f76b7f33",
		MethodNames: map[string]string{"Echo_Echo_Args": "echo", "Echo_Ping_Args": "ping_twice"},
	}
	if !reflect.DeepEqual(module, want) {
		t.Fatalf("module = %+v, want %+v", module, want)
	}
	for name, content := range map[string]string{
		"YARPC client":       thriftRWTestClient,
		"Apache header":      strings.Replace(thriftRWTestModule, "Code generated by thriftrw v1.32.0. DO NOT EDIT.", "Code generated by Thrift Compiler (0.18.1). DO NOT EDIT.", 1),
		"no ThriftModule":    strings.Replace(thriftRWTestModule, "var ThriftModule", "var OtherModule", 1),
		"plugin header only": "// Code generated by thriftrw-plugin-yarpc\npackage x\n",
	} {
		if _, ok, err := ParseThriftRWModule("x.go", content); ok || err != nil {
			t.Fatalf("%s: ParseThriftRWModule = %v, %v; want not a module", name, ok, err)
		}
	}
	if _, _, err := ParseThriftRWModule("x.go", strings.Replace(thriftRWTestModule, "c3e4e93d3bee132394d26e5ec61011e3f76b7f33", "not-a-sha", 1)); err == nil {
		t.Fatal("malformed SHA1 accepted")
	}
}

func TestDescribeThriftRWYARPCClientSpellsWireMethods(t *testing.T) {
	if !IsThriftRWYARPCClient(thriftRWTestClient) || IsThriftRWYARPCClient(thriftRWTestModule) {
		t.Fatal("YARPC client header detection is wrong")
	}
	parent, found, err := YARPCClientModuleImport("thrift/echo/echoclient/client.go", thriftRWTestClient)
	if err != nil || !found || parent != "example.test/thrift/echo" {
		t.Fatalf("module import = %q %v %v", parent, found, err)
	}
	shared := strings.Replace(thriftRWTestClient, "echo \"example.test/thrift/echo\"",
		"echo \"example.test/thrift/echo\"\n\tshared \"example.test/thrift/shared\"", 1)
	shared = strings.Replace(shared, "args := echo.Echo_Ping_Helper.Args()", "args := shared.Base_Ping_Helper.Args()", 1)
	if _, found, err := YARPCClientModuleImport("c.go", shared); err != nil || found {
		t.Fatalf("helpers through two packages = %v, %v; want no parent", found, err)
	}
	module, _, _ := ParseThriftRWModule("thrift/echo/echo.go", thriftRWTestModule)
	symbols, err := DescribeThriftRWYARPCClient(
		"thrift/echo/echoclient/client.go", "example.test/thrift/echo/echoclient",
		"example.test/thrift/echo", thriftRWTestClient, module,
	)
	if err != nil {
		t.Fatal(err)
	}
	want := []GeneratedSymbol{
		{Protocol: "thrift", ImportPath: "example.test/thrift/echo/echoclient", Package: "echoclient",
			ClientType: "Interface", Method: "Echo", Operation: "/echo.Echo/echo",
			Constructors: []string{"New"}, GeneratedPath: "thrift/echo/echoclient/client.go"},
		{Protocol: "thrift", ImportPath: "example.test/thrift/echo/echoclient", Package: "echoclient",
			ClientType: "Interface", Method: "Ping", Operation: "/echo.Echo/ping_twice",
			Constructors: []string{"New"}, GeneratedPath: "thrift/echo/echoclient/client.go"},
	}
	if !reflect.DeepEqual(symbols, want) {
		t.Fatalf("symbols = %+v\nwant %+v", symbols, want)
	}
	if _, err := DescribeThriftRWYARPCClient("c.go", "x", "example.test/other", thriftRWTestClient, module); err == nil {
		t.Fatal("a client that does not import the module was described")
	}
	twoServices := strings.Replace(thriftRWTestClient, `Service:      "Echo",
			ClientConfig: c,
		}, opts...),
	}`, `Service:      "Other",
			ClientConfig: c,
		}, opts...),
	}`, 1)
	if symbols, err := DescribeThriftRWYARPCClient("c.go", "x", "example.test/thrift/echo", twoServices, module); err != nil || len(symbols) != 0 {
		t.Fatalf("conflicting Service literals = %+v, %v; want no symbols", symbols, err)
	}
}
